(function(){'use strict';
const FLOORS=new Set(['ground-floor','ground-floor-frame','door-threshold','display-pad','work-yard']);
class CollisionWorld{
 constructor(){this.entries=new Map();}
 ray(o,d,max){let best=max;const ex=o[0]+d[0]*max,ez=o[2]+d[2]*max;for(const e of this.entries.values()){const b=e.bounds;if(Math.max(o[0],ex)<b.x0||Math.min(o[0],ex)>b.x1||Math.max(o[2],ez)<b.z0||Math.min(o[2],ez)>b.z1)continue;best=Math.min(best,e.col.ray(o,d,best));}if(best===max&&Math.abs(d[0])+Math.abs(d[2])<1e-8&&d[1]<0){const t=(TownWorldPlan.height(o[0],o[2])-o[1])/d[1];if(t>1e-4&&t<best)best=t;}return best;}
 floor(x,y,z,step=.6){const t=this.ray([x,y+step,z],[0,-1,0],600);return t<600?y+step-t:-Infinity;}
}
class StreamingTown{
 constructor(view,{seed=45256,onStatus=()=>{},interiorLoadDistance=10,interiorUnloadDistance=22}={}){this.view=view;this.seed=seed;this.onStatus=onStatus;this.interiorLoadDistance=interiorLoadDistance;this.interiorUnloadDistance=interiorUnloadDistance;if(interiorUnloadDistance<=interiorLoadDistance)throw Error('Interior unload radius must exceed load radius');this.shells=new Map();this.collision=new CollisionWorld();view.col=this.collision;this.chunks=new Map();this.meshes=new Map();this.interiors=new Map();this.pending=[];this.busy=null;this.token=0;this.wanted=new Map();this.errors=[];this.epoch=0;this.worker=new Worker('chunk-worker.js');this.worker.onmessage=e=>this.receive(e.data);this.worker.onerror=e=>{this.errors.push(e.message);this.busy=null;this.report();};this.update(0,TownWorldPlan.SIZE/2);}
 key(c){return c.x+','+c.z;}
 update(x,z){const c=TownWorldPlan.cell(x,z),center=this.key(c);if(center!==this.center){this.center=center;this.epoch++;const desired=TownWorldPlan.desired(x,z);this.wanted=new Map(desired.map(c=>[this.key(c),c]));for(const [key,chunk] of this.chunks)if(!this.wanted.has(key))this.unload(key);this.pending=desired.filter(c=>(!this.chunks.has(this.key(c))||this.chunks.get(this.key(c)).lod!==c.lod)&&this.busy?.key!==this.key(c));this.pump();this.commit();}
 const chunk=this.chunks.get(center);this.view.paused=!chunk||chunk.lod!==0;this.cullInteriors();this.report();
 }
 pump(){if(this.busy||!this.pending.length)return;const c=this.pending.shift(),key=this.key(c),wanted=this.wanted.get(key);if(!wanted||this.chunks.get(key)?.lod===c.lod||wanted.lod!==c.lod)return this.pump();const token=++this.token;this.busy={key,token,lod:c.lod};this.worker.postMessage({...c,seed:this.seed,token});}
 receive(data){if(this.busy?.token!==data.token)return;this.busy=null;const wanted=this.wanted.get(data.key);if(data.error){this.errors.push(data.error);this.report();this.pump();return;}
 if(wanted&&wanted.lod===data.lod){this.unload(data.key);this.chunks.set(data.key,data);const prefix='chunk:'+data.key+':';this.addMesh(prefix+'ground',data.terrain,data.bounds,!data.lod);for(const item of data.items){item.key=prefix+item.spec.id;item.chunk=data.key;item.saved=this.read(item.spec.id);if(!data.lod)this.addMesh(item.key,item.mesh,this.buildingBounds(item.spec),true);}if(data.lod)this.addMesh(prefix+'buildings',data.buildings,data.bounds,false);this.commit();delete data.buildings;delete data.terrain;for(const item of data.items)delete item.mesh;}
 // If a pending job changed LOD while in flight, queue its current version now.
 if(wanted&&this.chunks.get(data.key)?.lod!==wanted.lod&&!this.pending.some(c=>this.key(c)===data.key))this.pending.unshift(wanted);this.pump();this.report();}
 buildingBounds(s){const c=Math.abs(Math.cos(s.rot)),n=Math.abs(Math.sin(s.rot)),w=c*s.w+n*s.d,d=n*s.w+c*s.d;return {x0:s.x-w/2-3,x1:s.x+w/2+3,z0:s.z-d/2-3,z1:s.z+d/2+3};}
 addMesh(key,mesh,bounds,collision){this.view.renderer.drop(key);this.meshes.set(key,{key,mesh:{packed:mesh.packed}});if(collision)this.collision.entries.set(key,{bounds,col:new CastleWalk.Collider(mesh)});else this.collision.entries.delete(key);}
 unload(key){const c=this.chunks.get(key);if(!c)return;const prefix='chunk:'+key+':';for(const k of [...this.meshes.keys()])if(k.startsWith(prefix)){this.meshes.delete(k);this.collision.entries.delete(k);this.view.renderer.drop(k);}for(const i of c.items){this.interiors.delete(i.spec.id);this.shells.delete(i.spec.id);}this.chunks.delete(key);}
 commit(){const w=this.view.walker;this.view.renderer.setMeshes([...this.meshes.values()],{cx:w?.x||0,cz:w?.z||TownWorldPlan.SIZE/2,r:(TownWorldPlan.FAR+1)*TownWorldPlan.SIZE,h:28});if(this.view.invalidate)this.view.invalidate();else this.view.draw();for(const e of this.meshes.values())e.mesh={};}
 read(id){try{return JSON.parse(localStorage.getItem('fantasy-town:'+id)||'{}');}catch{return {};}}
 save(interior){const state=Object.fromEntries(interior.doors.map(d=>[d.id,d.open]));if(interior.item)interior.item.saved=state;try{localStorage.setItem('fantasy-town:'+interior.id,JSON.stringify(state));}catch{this.errors.push('Door changes could not be saved');}}
 interiorDistance(item,w){const s=item.spec,dx=w.x-s.x,dz=w.z-s.z,c=Math.cos(s.rot),n=Math.sin(s.rot),u=dx*c+dz*n,v=-dx*n+dz*c;return Math.hypot(Math.max(0,Math.abs(u)-s.w/2),Math.max(0,Math.abs(v)-s.d/2));}
 cullInteriors(){const w=this.view.walker;if(!w)return;for(const interior of this.interiors.values()){const item=interior.item,distance=this.interiorDistance(item,w),radius=interior.doors[0].open?this.interiorUnloadDistance:this.interiorLoadDistance;if(distance>radius){this.deactivate(item);return;}}}
 deactivate(item){const interior=this.interiors.get(item.spec.id);if(!interior)return;this.save(interior);for(const d of interior.doors){const key='chunk:'+item.chunk+':door:'+d.id;this.meshes.delete(key);this.collision.entries.delete(key);this.view.renderer.drop(key);}
  const shell=TownInteriors.create({...item.spec,includeInterior:false,movableEntrance:true}),m=CastleRender.meshParts(shell.parts.filter(p=>!FLOORS.has(p.role)),CastleGen.PALETTES[0]);this.addMesh(item.key,{packed:CastleRender.pack(m),p:m.p,k:m.k},this.buildingBounds(item.spec),true);const d=shell.doors[0];d.open=!!item.saved[d.id];const dm=CastleRender.meshParts(TownInteriors.doorParts(d),CastleGen.PALETTES[0]);this.addMesh('chunk:'+item.chunk+':door:'+d.id,{packed:CastleRender.pack(dm),p:dm.p,k:dm.k},this.buildingBounds(item.spec),true);this.interiors.delete(item.spec.id);this.shells.set(item.spec.id,{door:d});this.commit();}
 restoreNearby(){const w=this.view.walker;if(!w)return;for(const c of this.chunks.values())if(!c.lod)for(const item of c.items)if(!this.interiors.has(item.spec.id)&&item.saved[item.spec.id+':front']&&this.interiorDistance(item,w)<this.interiorLoadDistance){this.activate(item);return;}}
 nearby(){const w=this.view.walker;if(!w)return [];const candidates=[];for(const c of this.chunks.values())if(!c.lod)for(const item of c.items){const interior=this.interiors.get(item.spec.id);if(interior){for(const d of interior.doors){const distance=Math.hypot(w.x-d.x,w.z-d.z,w.y-d.y);if(distance<2.5)candidates.push({item,door:d,distance});}}else{const distance=Math.hypot(w.x-item.entry.x,w.z-item.entry.z,w.y-item.entry.y);if(distance<2.5)candidates.push({item,distance});}}return candidates.sort((a,b)=>a.distance-b.distance);}
 activate(item){const interior=TownInteriors.create({...item.spec,includeInterior:true}),parts=interior.parts.filter(p=>!FLOORS.has(p.role)),m=CastleRender.meshParts(parts,CastleGen.PALETTES[0]);interior.item=item;this.shells.delete(item.spec.id);this.interiors.set(item.spec.id,interior);this.addMesh(item.key,{packed:CastleRender.pack(m),p:m.p,k:m.k},this.buildingBounds(item.spec),true);for(const d of interior.doors)d.open=!!item.saved[d.id];this.updateDoors(item,interior);return interior;}
 updateDoors(item,interior){for(const d of interior.doors){const key='chunk:'+item.chunk+':door:'+d.id,m=CastleRender.meshParts(TownInteriors.doorParts(d),CastleGen.PALETTES[0]);this.addMesh(key,{packed:CastleRender.pack(m),p:m.p,k:m.k},this.buildingBounds(item.spec),true);}this.save(interior);this.commit();}
 interact(){const target=this.nearby()[0];if(!target)return false;let {item,door}=target,interior=this.interiors.get(item.spec.id);if(!interior){interior=this.activate(item);door=interior.doors[0];door.open=true;}else{const w=this.view.walker;if(door.open&&Math.hypot(w.x-door.x,w.z-door.z)<.75&&Math.abs(w.y-door.y)<2)return false;door.open=!door.open;}this.updateDoors(item,interior);return true;}
 stats(){const levels=[...this.chunks.values()].flatMap(c=>c.items.map(i=>i.spec.floor));return {courtyards:this.chunks.size,elevationRange:levels.length?Math.max(...levels)-Math.min(...levels):0,chunks:this.chunks.size,near:[...this.chunks.values()].filter(c=>!c.lod).length,buildings:[...this.chunks.values()].reduce((n,c)=>n+c.items.length,0),interiors:this.interiors.size,interiorUnloadDistance:this.interiorUnloadDistance,shells:this.shells.size,meshes:this.view.renderer.cache.size,bufferMiB:[...this.view.renderer.cache.values()].reduce((n,g)=>n+g.bytes,0)/1048576,pending:this.pending.length+(this.busy?1:0),center:this.center,errors:[...this.errors]};}
 report(){const now=performance.now();if(this.lastReport!=null&&now-this.lastReport<250)return;this.lastReport=now;this.onStatus(this.stats());}
 destroy(){this.worker.terminate();for(const key of [...this.chunks.keys()])this.unload(key);this.meshes.clear();this.collision.entries.clear();}
}
window.StreamingTown=StreamingTown;
})();
